def get_value_at_index():
    id_sequence = [10, 20, 30, 40, 50]  # Example array
    try:
        index_input = input("Enter an index value: ")
        index = int(index_input)
        if 0 <= index < len(id_sequence):
            return id_sequence[index]
        else:
            print("Error: Index out of range.")
            return None
    except ValueError:
        print("Error: Please enter a valid integer.")
        return None

zh-CN:
def get_value_at_index():
    id_sequence = [10, 20, 30, 40, 50]  # 示例数组，可根据需要修改
    try:
        user_input = input("请输入索引值: ").strip()
        # 检查是否为空输入
        if not user_input:
            return -1
        # 尝试转换为整数
        index = int(user_input)
        # 检查是否为负数
        if index < 0:
            return -1
        # 检查索引是否在范围内
        if index >= len(id_sequence):
            return -1
        # 返回对应值
        return id_sequence[index]
    except (ValueError, TypeError):
        return -1

