def obtener_valor_en_indice():
    id_sequence = [10, 20, 30, 40, 50]  # Ejemplo de matriz

    while True:
        try:
            indice = int(input("Ingrese un valor de índice: "))
            if 0 <= indice < len(id_sequence):
                return id_sequence[indice]
            else:
                print(f"Índice fuera de rango. Por favor, ingrese un valor entre 0 y {len(id_sequence) - 1}.")
        except ValueError:
            print("Entrada inválida. Por favor, ingrese un número entero.")
        except Exception as e:
            print(f"Ocurrió un error: {e}")

# Llamada a la función
resultado = obtener_valor_en_indice()
print(f"El valor en el índice es: {resultado}")

